const expectedSlugs = [
  "tarih", "felsefe", "psikoloji", "sosyoloji", "kisisel-gelisim", "is-dunyasi", "girisimcilik", "finans", "ekonomi", "teknoloji", "yapay-zeka", "programlama", "hukuk", "egitim", "siyaset", "iletisim", "sanat", "mimarlik", "saglik", "spor", "yemek-ve-gastronomi", "seyahat", "din-ve-inanc",
] as const;

const profileBySlug = new Map(profiles.map((profile) => [profile.slug, profile]));

export function isInformationalGuideSlug(slug: string): boolean {
  return expectedSlugs.includes(slug as (typeof expectedSlugs)[number]);
}

export function getEducationGuideDefinition(slug: string): InformationalGuideDefinition {
  const profile = profileBySlug.get(slug);
  if (!profile) throw new Error(`Informational guide definition missing: ${slug}`);
  return build(profile);
}

export const INFORMATIONAL_GUIDE_DEFINITIONS = expectedSlugs.map((slug) => getEducationGuideDefinition(slug));
